    cached_s3_storage_bytes?: number;
    /**
     * Total 30-day loadbalancer traffic in bytes; COALESCE traffic.*.30d_total then bytes.*.30d_total
     */
    cached_lb_traffic_30d_bytes?: number;
    /**
     * Total log ingestion count in last 30 days
     */
    cached_logs_30d?: number;
    /**
     * Average active metric series in last 30 days
     */
    cached_metrics_30d_avg?: number;
    /**
     * Last time cached metrics were updated
     */
    cached_metrics_updated_at?: (string) | null;
    /**
     * Cached S3 bucket count after exclude_archived (owned plus Loopback-delegated; Spec 825 / 864)
     */
    cached_s3_bucket_count?: number;
    /**
     * Cached S3 object count after exclude_archived (owned plus Loopback-delegated; Spec 825 / 864)
     */
    cached_s3_object_count?: number;
    /**
     * Cached S3 rollups per effective region (S3Bucket.region_id; Spec 865 / 896)
     */
    cached_s3_by_region?: unknown;
    /**
     * Cached loadbalancer instance count
     */
    cached_lb_count?: number;
    /**
     * Cached inbound 30-day loadbalancer traffic in bytes; COALESCE traffic.in.30d_total then bytes.in.30d_total
     */
    cached_lb_traffic_30d_in_bytes?: number;
    /**
     * Cached outbound 30-day loadbalancer traffic in bytes; COALESCE traffic.out.30d_total then bytes.out.30d_total
     */
    cached_lb_traffic_30d_out_bytes?: number;
    /**
     * Cached total K8sVolume count across all workspaces
     */
    cached_volume_count?: number;
    /**
     * Cached total K8sVolume capacity in bytes across all workspaces
     */
    cached_volume_capacity_bytes?: number;
    /**
     * Portal-visible K8sCluster count: cluster and workspace not archived, neither kind generic (Spec 630 / 781)
     */
    cached_k8s_cluster_count?: number;
    /**
     * Non-archived Workspace count for this organization (Spec 630)
     */
    cached_workspace_count?: number;
    /**
     * Non-archived Endpoint count for this organization (Spec 630)
     */
    cached_endpoint_count?: number;
    /**
     * Non-archived Endpoints with state=CRITICAL (Spec 630)
     */
    cached_endpoint_down_count?: number;
    /**
     * OrganizationMembership count (Spec 630)
     */
    cached_member_count?: number;
    /**
     * Memberships whose user.is_active is True (Spec 630)
     */
    cached_member_active_count?: number;
    /**
     * Active maintenances for org plus system-wide (Spec 630 / 532)
     */
    cached_active_maintenances_count?: number;
    /**
     * Open incidents for org plus system-wide (Spec 630)
     */
    cached_open_incidents_count?: number;
    /**
     * Active downtimes for this organization (Spec 630)
     */
    cached_active_downtimes_count?: number;
    /**
     * Firing alerts for this organization (Spec 630)
     */
    cached_firing_alerts_count?: number;
    /**
     * Total monthly product cost across all OrganizationProducts (cached)
     */
    cached_total_product_cost?: (string) | null;
    /**
     * Last time cached_total_product_cost was recalculated
     */
    cached_product_cost_updated_at?: (string) | null;
