/**
 * Simple Organization serializer for nested representations.
 *
 * Includes `url` field for direct navigation.
 */
export type OrganizationSimple = {
    readonly id: string;
    readonly name: string;
    /**
     * The display name is used to display the object in the UI. It can be different from the name.
     */
    readonly display_name: (string) | null;
    readonly slug: (string) | null;
    readonly reconciliation_running: boolean;
    /**
     * * `generic` - Generic
     */
    readonly kind: 'generic';
    readonly legal_name: string;
    /**
     * 3-8 digit numeric tenant identifier
     */
    readonly tenant_id: (string) | null;
    /**
     * 8-digit numeric PIN for support authentication
     */
    readonly support_pin: (string) | null;
    /**
     * High priority organization flag
     */
    readonly priority: boolean;
    readonly url: string;
    /**
     * ID of the external system object managing this organization
     */
    readonly upstream_organization_id: (string) | null;
    /**
     * Identifier of the external system managing this organization
     */
    readonly upstream_system_id: (string) | null;
    readonly keycloak_org_id: (string) | null;
};

/**
 * Serializer for Organization API Keys (kind='org_api_key').
 * token is only included on create (write-once).
 * Spec 488: System and Organization API Keys
 */
export type OrgAPIKey = {
    readonly id: string;
    name: string;
    /**
     * Access mode for system_api_key and org_api_key credentials. Ignored for other kinds.
     *
     * * `read` - Read
     * * `read_write` - Read/Write
     */
    access_mode?: ('read' | 'read_write' | '') | null;
    readonly created_at: string;
    /**
     * Timestamp of the last successful authentication using this credential.
     */
    readonly last_used_at: (string) | null;
    /**
     * Return raw token only on create (stored in context by view).
     */
    readonly token: (string) | null;
};

/**
 * Access mode for system_api_key and org_api_key credentials. Ignored for other kinds.
 *
 * * `read` - Read
 * * `read_write` - Read/Write
 */
export type access_mode = 'read' | 'read_write' | '';

/**
 * Serializer for Organization API Keys (kind='org_api_key').
 * token is only included on create (write-once).
 * Spec 488: System and Organization API Keys
 */
export type OrgAPIKeyRequest = {
    name: string;
    /**
     * Access mode for system_api_key and org_api_key credentials. Ignored for other kinds.
     *
     * * `read` - Read
     * * `read_write` - Read/Write
     */
    access_mode?: ('read' | 'read_write' | '') | null;
};

