/**
 * Basis-Serializer für alle ManagedObject Detail-Endpoints.
 *
 * Enthält alle generischen Felder eines ManagedObjects.
 * Subclasses erweitern diese Liste mit model-spezifischen Feldern.
 *
 * Inkludiert:
 * - Alle BaseObject Felder (id, name, display_name, labels, annotations, timestamps)
 * - Alle ManagedObject Felder (state, reconciliation, discovery, repair, conditions, etc.)
 * - organization/workspace als generische ManagedObject-Referenzen (mit URL)
 * - created: Kombifeld (created_at, created_at_humanized, created_by)
 * - url: Absolute URL zum Object (via get_absolute_url())
 *
 * Usage:
 * class K8sClusterDetailSerializer(ManagedObjectDetailSerializer):
 * class Meta(ManagedObjectDetailSerializer.Meta):
 * model = K8sCluster
 * fields = ManagedObjectDetailSerializer.Meta.fields + ['kubeconfig', 'nodes']
 */
export type PatchedAlertCategoryRequest = {
    /**
     * Object name
     */
    name?: string;
    /**
     * The display name is used to display the object in the UI. It can be different from the name.
     */
    display_name?: (string) | null;
    labels?: unknown;
    annotations?: unknown;
    /**
     * Persists all Object Logs in the database
     */
    debug_mode?: boolean;
    /**
     * * `loopback` - Loopback
     * * `hetzner_cloud` - HETZNER Cloud
     * * `hetzner_robot` - HETZNER Robot
     * * `bare_metal` - Bare-Metal
     * * `powerdns` - PowerDNS
     * * `cloudflare` - Cloudflare
     * * `rook-ceph` - Rook Ceph
     * * `polycrate` - Polycrate
     * * `kubernetes` - Kubernetes
     * * `helm` - Helm
     * * `generic` - Generic
     * * `victorialogs` - VictoriaLogs
     * * `system` - System
     */
    provider?: 'loopback' | 'hetzner_cloud' | 'hetzner_robot' | 'bare_metal' | 'powerdns' | 'cloudflare' | 'rook-ceph' | 'polycrate' | 'kubernetes' | 'helm' | 'generic' | 'victorialogs' | 'system';
    provider_reference?: (string) | null;
    provider_id?: (string) | null;
    reconciliation_enabled?: boolean;
    platform_service?: boolean;
    /**
     * * `generic` - Generic
     */
    kind?: 'generic';
    /**
     * Tolerations match conditions. If a toleration for a condition exists for an object, the condition will not be applied.
     */
    tolerations?: unknown;
    /**
     * Archived objects are not shown in the UI and are not managed by the API.
     */
    archived?: boolean;
    archived_at?: (string) | null;
    /**
     * The reason why the object was archived
     */
    archived_reason?: (string) | null;
    /**
     * Criticality level. Null = inherit from workspace, then org. Explicit value overrides inheritance.
     *
     * * `high` - High
     * * `medium` - Medium
     * * `low` - Low
     */
    criticality?: ('high' | 'medium' | 'low' | '') | null;
    /**
     * Target availability in % (overrides SystemConfig default). Null = use SystemConfig DEFAULT_TARGET_AVAILABILITY.
     */
    target_availability?: (string) | null;
    /**
     * Internal SLO target in %. Null = use SystemConfig DEFAULT_SLO_TARGET
     */
    slo_target?: (string) | null;
    /**
     * Calculated SLO availability in % (updated in reconcile)
     */
    slo_availability?: string;
    /**
     * Contractual SLA target in %. Null = use SystemConfig DEFAULT_SLA_TARGET
     */
    sla_target?: (string) | null;
    /**
     * Calculated SLA availability in % (updated in reconcile)
     */
    sla_availability?: string;
    description?: string;
    sort_order?: number;
    /**
     * Inactive categories are skipped when resolving new mappings.
     */
    active?: boolean;
};

